#!/usr/bin/env node
/**
 * Copies hardware/joint-map.json and hardware/calibration.json into dist/ after
 * a build, so an installed copy of @sesame-lab/sesame-model is self-contained
 * and `loadJointMap()` / `loadCalibration()` work without a repository
 * checkout.
 *
 * The repository files stay the single source of truth: they are generated by
 * `node scripts/build-joint-map.mjs` and `node scripts/build-calibration.mjs`
 * and validated by `pnpm validate:joint-map` / `pnpm validate:calibration`.
 * This only ever copies, never edits.
 *
 * The copied calibration is the *reference* document — entirely carried
 * forward, nothing measured. A calibrated robot's document is loaded at run
 * time via `$SESAME_CALIBRATION` or an explicit path; it is deliberately not
 * something you bake into a package.
 */
import { copyFileSync, mkdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

const here = dirname(fileURLToPath(import.meta.url));
const pkgRoot = resolve(here, '..');
const repoRoot = resolve(pkgRoot, '..', '..');

mkdirSync(resolve(pkgRoot, 'dist'), { recursive: true });

for (const name of ['joint-map.json', 'calibration.json']) {
  const src = resolve(repoRoot, 'hardware', name);
  const dest = resolve(pkgRoot, 'dist', name);
  copyFileSync(src, dest);
  console.error(`copied hardware/${name} -> ${dest.slice(pkgRoot.length + 1)}`);
}
